CREATE TABLE ibexa_content (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, content_type_id INTEGER DEFAULT 0 NOT NULL, current_version INTEGER DEFAULT NULL, initial_language_id BIGINT DEFAULT 0 NOT NULL, language_mask BIGINT DEFAULT 0 NOT NULL, modified INTEGER DEFAULT 0 NOT NULL, name VARCHAR(255) DEFAULT NULL, owner_id INTEGER DEFAULT 0 NOT NULL, published INTEGER DEFAULT 0 NOT NULL, remote_id VARCHAR(100) DEFAULT NULL, section_id INTEGER DEFAULT 0 NOT NULL, status INTEGER DEFAULT 0, is_hidden BOOLEAN DEFAULT '0' NOT NULL);
